using Contoso.Pricing;

namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private PriceCalculator _calculator = null!;

    [TestInitialize]
    public void Setup() => _calculator = new PriceCalculator();

    // ── CalculateTotal: DataRow-driven tests ────────────────────────────

    [TestMethod]
    [DataRow(10.00, 1, 0.0,  10.00,  DisplayName = "Single item, no tax")]
    [DataRow(10.00, 5, 0.0,  50.00,  DisplayName = "Multiple items, no tax")]
    [DataRow(10.00, 1, 0.10, 11.00,  DisplayName = "Single item, 10% tax")]
    [DataRow(25.50, 3, 0.08, 82.62,  DisplayName = "Fractional price, 8% tax")]
    [DataRow(0.00,  5, 0.10, 0.00,   DisplayName = "Zero price")]
    [DataRow(10.00, 0, 0.10, 0.00,   DisplayName = "Zero quantity")]
    [DataRow(99.99, 1, 1.0,  199.98, DisplayName = "Maximum tax rate (100%)")]
    public void CalculateTotal_ReturnsExpected(
        double unitPrice, int quantity, double taxRate, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expected, result);
    }

    [TestMethod]
    [DataRow(-1.00, 1,  0.10, DisplayName = "Negative unit price throws")]
    [DataRow(10.00, -1, 0.10, DisplayName = "Negative quantity throws")]
    [DataRow(10.00, 1,  -0.1, DisplayName = "Negative tax rate throws")]
    [DataRow(10.00, 1,  1.01, DisplayName = "Tax rate > 1 throws")]
    public void CalculateTotal_InvalidInput_ThrowsArgumentOutOfRangeException(
        double unitPrice, int quantity, double taxRate)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));
    }

    // ── ApplyDiscount: DynamicData-driven tests ─────────────────────────

    public static IEnumerable<object[]> DiscountTestData =>
    [
        [200.00m, 0m,   200.00m],  // No discount
        [200.00m, 10m,  180.00m],  // 10% off
        [200.00m, 50m,  100.00m],  // Half off
        [200.00m, 100m, 0.00m],    // Full discount
        [0.00m,   50m,  0.00m],    // Zero price
        [99.99m,  25m,  74.9925m], // Fractional result
    ];

    private static string DiscountDisplayName(MethodInfo _, object[] data)
        => $"Price {data[0]:C} with {data[1]}% discount → {data[2]:C}";

    [TestMethod]
    [DynamicData(nameof(DiscountTestData), DynamicDataDisplayName = nameof(DiscountDisplayName))]
    public void ApplyDiscount_ReturnsExpected(
        decimal price, decimal discountPercent, decimal expected)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expected, result);
    }

    public static IEnumerable<object[]> InvalidDiscountData =>
    [
        [-1m,  "Negative discount"],
        [101m, "Discount exceeds 100%"],
    ];

    private static string InvalidDiscountDisplayName(MethodInfo _, object[] data)
        => $"Discount {data[0]}% throws ({data[1]})";

    [TestMethod]
    [DynamicData(nameof(InvalidDiscountData), DynamicDataDisplayName = nameof(InvalidDiscountDisplayName))]
    public void ApplyDiscount_InvalidPercent_ThrowsArgumentOutOfRangeException(
        decimal discountPercent, string _description)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(100m, discountPercent));
    }

    // ── FormatPrice: quick DataRow coverage ──────────────────────────────

    [TestMethod]
    [DataRow(19.99, "$", "$19.99",  DisplayName = "USD format")]
    [DataRow(19.99, "€", "€19.99",  DisplayName = "EUR format")]
    [DataRow(5.5,   "$", "$5.50",   DisplayName = "Pads to two decimals")]
    [DataRow(0.0,   "$", "$0.00",   DisplayName = "Zero price")]
    public void FormatPrice_ReturnsExpected(
        double price, string symbol, string expected)
    {
        var result = _calculator.FormatPrice((decimal)price, symbol);

        Assert.AreEqual(expected, result);
    }
}

